import XCTest
final class RoomTests: XCTestCase {
    func testSend() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        sleep(2)
        let composer = app.textViews.firstMatch
        if composer.waitForExistence(timeout: 5) {
            composer.tap()
            composer.typeText("status update")
        } else {
            let field = app.textFields.firstMatch
            XCTAssertTrue(field.waitForExistence(timeout: 5), "No message composer found")
            field.tap()
            field.typeText("status update")
        }
        sleep(1)
        print("COMPOSER STATE:\n\(app.debugDescription)")
    }
}
EOF
